"""Berggren descent: canonical address decoding of a primitive Pythagorean triple."""

from __future__ import annotations

from math import gcd
from typing import List, Tuple

Triple = Tuple[int, int, int]

ROOT: Triple = (3, 4, 5)


def is_ppt(t: Triple) -> bool:
    """Positive entries, coprime legs, and a^2 + b^2 = c^2."""
    a, b, c = t
    return a > 0 and b > 0 and c > 0 and a * a + b * b == c * c and gcd(a, b) == 1


def step(i: int, t: Triple) -> Triple:
    """The three Berggren branch maps, indexed 0 = A, 1 = B, 2 = C."""
    a, b, c = t
    if i == 0:
        return (a - 2 * b + 2 * c, 2 * a - b + 2 * c, 2 * a - 2 * b + 3 * c)
    if i == 1:
        return (a + 2 * b + 2 * c, 2 * a + b + 2 * c, 2 * a + 2 * b + 3 * c)
    return (-a + 2 * b + 2 * c, -2 * a + b + 2 * c, -2 * a + 2 * b + 3 * c)


def walk(word: List[int]) -> Triple:
    """Node reached from the root; the word is read right to left."""
    t = ROOT
    for i in reversed(word):
        t = step(i, t)
    return t


def parent(i: int, t: Triple) -> Triple:
    """Inverse of `step(i, .)`: the three unimodular parent maps."""
    a, b, c = t
    if i == 0:
        return (a + 2 * b - 2 * c, -2 * a - b + 2 * c, -2 * a - 2 * b + 3 * c)
    if i == 1:
        return (a + 2 * b - 2 * c, 2 * a + b - 2 * c, -2 * a - 2 * b + 3 * c)
    return (-a - 2 * b + 2 * c, 2 * a + b - 2 * c, -2 * a - 2 * b + 3 * c)


def decode_address(t: Triple) -> List[int]:
    """Return the unique word w with walk(w) = t, for a primitive triple with odd first leg.

    The descent uses the two linear forms u = a + 2b - 2c and v = 2a + b - 2c.  For a
    primitive triple other than the root, u is odd hence never zero, v vanishes only at the
    root, and u and v are never both nonpositive.  The sign pattern therefore selects exactly
    one parent:

        u > 0, v < 0  ->  branch A        u > 0, v > 0  ->  branch B
        u < 0, v > 0  ->  branch C

    Each parent step sends the hypotenuse c to 3c - 2a - 2b, a decrease of at least 8, so the
    loop terminates in at most (c - 5) / 8 iterations; empirically the decrease is geometric
    and the count is O(log c), the worst case O(sqrt(c)) occurring along the slow branch.
    Every iteration costs O(1) arithmetic operations on integers of size O(log c).
    """
    if not is_ppt(t) or t[0] % 2 != 1:
        raise ValueError("expected a primitive Pythagorean triple with odd first leg")
    word: List[int] = []
    while t != ROOT:
        a, b, c = t
        u = a + 2 * b - 2 * c
        v = 2 * a + b - 2 * c
        if u > 0 and v < 0:
            letter = 0
        elif u > 0 and v > 0:
            letter = 1
        else:
            letter = 2
        word.append(letter)
        t = parent(letter, t)
    return word


def address_string(word: List[int]) -> str:
    return "".join("ABC"[i] for i in word) or "(root)"


if __name__ == "__main__":
    for t in [(3, 4, 5), (5, 12, 13), (15, 8, 17), (33, 56, 65), (63, 16, 65),
              (253, 204, 325), (323, 36, 325)]:
        w = decode_address(t)
        assert walk(w) == t, "round trip failed"
        print(f"{str(t):<18} -> address {address_string(w):<12} depth {len(w)}")

"""Resonance enumeration and interference collapse: factoring by congruence of squares."""

from __future__ import annotations

from math import gcd
from typing import Dict, List, Optional, Tuple

Triple = Tuple[int, int, int]

ROOT: Triple = (3, 4, 5)


def step(i: int, t: Triple) -> Triple:
    a, b, c = t
    if i == 0:
        return (a - 2 * b + 2 * c, 2 * a - b + 2 * c, 2 * a - 2 * b + 3 * c)
    if i == 1:
        return (a + 2 * b + 2 * c, 2 * a + b + 2 * c, 2 * a + 2 * b + 3 * c)
    return (-a + 2 * b + 2 * c, -2 * a + b + 2 * c, -2 * a + 2 * b + 3 * c)


def enumerate_nodes(bound: int) -> Dict[Triple, List[int]]:
    """All nodes of hypotenuse at most `bound`, with one address each.

    Correct because every branch strictly increases the hypotenuse (indeed by at least 8),
    so the depth-first expansion may be pruned as soon as the bound is exceeded.  The cost is
    proportional to the number of primitive triples of hypotenuse at most `bound`, which is
    asymptotically bound / (2*pi).
    """
    found: Dict[Triple, List[int]] = {ROOT: []}
    stack: List[Tuple[Triple, List[int]]] = [(ROOT, [])]
    while stack:
        node, word = stack.pop()
        for i in range(3):
            child = step(i, node)
            if child[2] <= bound:
                child_word = [i] + word
                found[child] = child_word
                stack.append((child, child_word))
    return found


def resonant_nodes(N: int) -> List[Tuple[List[int], Triple]]:
    """All nodes whose hypotenuse is exactly N, sorted by address length."""
    out = [(w, t) for t, w in enumerate_nodes(N).items() if t[2] == N]
    out.sort(key=lambda pair: (len(pair[0]), pair[0]))
    return out


def interference_gcd(t1: Triple, t2: Triple, N: int) -> int:
    """gcd(a1*a2 - b1*b2, N), the factor delivered by an interfering resonant pair."""
    a1, b1, _ = t1
    a2, b2, _ = t2
    return gcd(a1 * a2 - b1 * b2, N)


def certifies_congruence_of_squares(t1: Triple, t2: Triple, N: int) -> bool:
    """Check (a1 a2)^2 = (b1 b2)^2 mod N, the identity underlying every collapse."""
    a1, b1, _ = t1
    a2, b2, _ = t2
    return ((a1 * a2) ** 2 - (b1 * b2) ** 2) % N == 0


def collapse(N: int) -> Optional[Tuple[List[int], List[int], int, int]]:
    """Factor N by interference, or report that no interference pair exists.

    Returns (address1, address2, d, N // d) where d is an exact nontrivial proper divisor,
    or None when the resonance multiplicity is 0 (N is inaudible: some prime factor is
    3 mod 4) or 1 (N is a prime power, so no pair exists).

    Complexity: the enumeration dominates at Theta(N) node expansions; the collapse itself
    is a single gcd, O(log^2 N) bit operations.  The exponential-in-log-N cost of the search
    is exactly the kinematic barrier: at the first depth n where a resonance can occur,
    3^n >= sqrt(N/5).
    """
    res = resonant_nodes(N)
    for i in range(len(res)):
        for j in range(i + 1, len(res)):
            assert certifies_congruence_of_squares(res[i][1], res[j][1], N)
            d = interference_gcd(res[i][1], res[j][1], N)
            if 1 < d < N:
                return res[i][0], res[j][0], d, N // d
    return None


def address_string(word: List[int]) -> str:
    return "".join("ABC"[i] for i in word) or "(root)"


if __name__ == "__main__":
    for N in (65, 325, 625, 1105, 4225, 32045):
        out = collapse(N)
        mult = len(resonant_nodes(N))
        if out is None:
            print(f"N = {N:>6}: multiplicity {mult} -> no interference pair (prime power)")
        else:
            w1, w2, d, e = out
            print(f"N = {N:>6}: multiplicity {mult} -> {address_string(w1)} x "
                  f"{address_string(w2)} gives {N} = {d} * {e}")
